window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e665c53516e1c945"]={"versions": [{"id": "FIG-e665c53516e1c945", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Blockschaltbild der AUTOSAR-Classic-ECU-Architektur (AUTOSAR Layered Architecture). Das Diagramm verortet das Basissoftware-Modul <code>StbM</code> (Synchronized Time-Base Manager) als AUTOSAR-Service innerhalb der Basissoftware (BSW) und stellt dessen Einbindung über die AUTOSAR Runtime Environment (RTE) zu den Application Software Components (SW-Cs) sowie zu benachbarten BSW-Schichten dar. Eine Legende klassifiziert Schnittstellentypen und API-Kategorien (API 0, API 1, API 2).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Application Layer</strong>: Mehrere <code>Application Software Component</code>-Blöcke, angebunden über gepunktete Ports des Typs <code>AUTOSAR Interface</code>.</li>\n<li><strong>RTE-Schicht</strong>: <code>AUTOSAR Runtime Environment (RTE)</code> als horizontaler Abstraktionsbalken zwischen Applikationsebene und BSW.</li>\n<li><strong>Basissoftware (BSW)</strong>:</li>\n<li><code>StbM</code> (hervorgehoben): BSW-Service mit oberseitigem <code>AUTOSAR Interface</code> (gepunktet, API 2 / VFB & RTE relevant) zur RTE sowie unterseitigem <code>Standardized Interface</code> (gestreift, API 0).</li>\n<li><code>Operating System</code>: Verfügt über ein oberseitiges <code>Standardized Interface</code> (API 1 RTE relevant) und ein vertikales <code>Standardized Interface</code> (API 0).</li>\n<li><code>Communication</code>: Verfügt über ein oberseitiges <code>Standardized Interface</code> (API 1 RTE relevant) und ein unterseitiges <code>Standardized Interface</code> (API 0).</li>\n<li><code>ECU Abstraction</code>: Oberseitig <code>AUTOSAR Interface</code> (API 2) und unterseitig <code>Standardized Interface</code> (API 0).</li>\n<li><code>Microcontroller Abstraction</code> (MCAL): Schnittstellenblock <code>Standardized Interface</code> (API 0).</li>\n<li><code>Complex Device Drivers</code>: Durchgängiger Block mit oberseitigem <code>AUTOSAR Interface</code> (API 2).</li>\n<li><strong>Legende</strong>:</li>\n<li>Schnittstellenarten: <code>AUTOSAR Interface</code> (Punkte-Muster), <code>Standardized Interface</code> (Streifen-Muster).</li>\n<li>Schichtkategorien: <code>AUTOSAR Software Component</code>, <code>ECU Firmware</code>, <code>Standard Software</code>.</li>\n<li>API-Klassifikation: <code>API 2 VFB &amp; RTE relevant</code> (blauer Doppelpfeil), <code>API 1 RTE relevant</code> (oranger Pfeil), <code>API 0</code> (grüner Haken-/Verbindungspfeil).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Zwei farbige Leitfragen-Pfeile fokussieren auf das oberseitige <code>AUTOSAR Interface</code> des StbM:</li>\n<li>Ein oranger Pfeil fragt: <em>„How does the SW-C access the Synchronized Time-base Mgr?“</em> (Client-Server- bzw. Sender-Receiver-Aufruf einer SW-C an den StbM via RTE).</li>\n<li>Ein gelber Pfeil fragt: <em>„How the SW-C gets notified from the Synchronized Timebase Manager?“</em> (Rückmeldung/Benachrichtigung des StbM an die SW-C via RTE).</li>\n<li>Auf BSW-Ebene (API 0) interagiert der StbM über standardisierte C-Schnittstellen (<code>Standardized Interface</code>) direkt über den horizontalen Bus-/Signalpfad mit <code>Operating System</code>, <code>Communication</code>, <code>ECU Abstraction</code> und <code>Microcontroller Abstraction</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Schaubild veranschaulicht normativ die Rolle des StbM als AUTOSAR-Service mit VFB-Schnittstelle: SW-Cs dürfen ausschließlich über die durch die RTE vermittelten AUTOSAR Interfaces (Ports) auf den StbM zugreifen und von ihm benachrichtigt werden.</li>\n<li>Direkte C-Funktionsaufrufe (API 0 / Standardized Interfaces) zwischen SW-Cs und StbM sind architektonisch unzulässig; API 0 ist BSW-internen Modulbeziehungen (z. B. Kopplung an Bus-Treiber/Communication Stack oder OS-Timer) vorbehalten.</li>\n</ul>"}, {"id": "FIG-72d4d3b7c5090e86", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Blockschaltbild der AUTOSAR-Classic-ECU-Architektur (AUTOSAR Layered Architecture). Das Diagramm verortet das Basissoftware-Modul <code>StbM</code> (Synchronized Time-Base Manager) als AUTOSAR-Service innerhalb der Basissoftware (BSW) und stellt dessen Einbindung über die AUTOSAR Runtime Environment (RTE) zu den Application Software Components (SW-Cs) sowie zu benachbarten BSW-Schichten dar. Eine Legende klassifiziert Schnittstellentypen und API-Kategorien (API 0, API 1, API 2).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Application Layer</strong>: Mehrere <code>Application Software Component</code>-Blöcke, angebunden über gepunktete Ports des Typs <code>AUTOSAR Interface</code>.</li>\n<li><strong>RTE-Schicht</strong>: <code>AUTOSAR Runtime Environment (RTE)</code> als horizontaler Abstraktionsbalken zwischen Applikationsebene und BSW.</li>\n<li><strong>Basissoftware (BSW)</strong>:</li>\n<li><code>StbM</code> (hervorgehoben): BSW-Service mit oberseitigem <code>AUTOSAR Interface</code> (gepunktet, API 2 / VFB & RTE relevant) zur RTE sowie unterseitigem <code>Standardized Interface</code> (gestreift, API 0).</li>\n<li><code>Operating System</code>: Verfügt über ein oberseitiges <code>Standardized Interface</code> (API 1 RTE relevant) und ein vertikales <code>Standardized Interface</code> (API 0).</li>\n<li><code>Communication</code>: Verfügt über ein oberseitiges <code>Standardized Interface</code> (API 1 RTE relevant) und ein unterseitiges <code>Standardized Interface</code> (API 0).</li>\n<li><code>ECU Abstraction</code>: Oberseitig <code>AUTOSAR Interface</code> (API 2) und unterseitig <code>Standardized Interface</code> (API 0).</li>\n<li><code>Microcontroller Abstraction</code> (MCAL): Schnittstellenblock <code>Standardized Interface</code> (API 0).</li>\n<li><code>Complex Device Drivers</code>: Durchgängiger Block mit oberseitigem <code>AUTOSAR Interface</code> (API 2).</li>\n<li><strong>Legende</strong>:</li>\n<li>Schnittstellenarten: <code>AUTOSAR Interface</code> (Punkte-Muster), <code>Standardized Interface</code> (Streifen-Muster).</li>\n<li>Schichtkategorien: <code>AUTOSAR Software Component</code>, <code>ECU Firmware</code>, <code>Standard Software</code>.</li>\n<li>API-Klassifikation: <code>API 2 VFB &amp; RTE relevant</code> (blauer Doppelpfeil), <code>API 1 RTE relevant</code> (oranger Pfeil), <code>API 0</code> (grüner Haken-/Verbindungspfeil).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Zwei farbige Leitfragen-Pfeile fokussieren auf das oberseitige <code>AUTOSAR Interface</code> des StbM:</li>\n<li>Ein oranger Pfeil fragt: <em>„How does the SW-C access the Synchronized Time-base Mgr?“</em> (Client-Server- bzw. Sender-Receiver-Aufruf einer SW-C an den StbM via RTE).</li>\n<li>Ein gelber Pfeil fragt: <em>„How the SW-C gets notified from the Synchronized Timebase Manager?“</em> (Rückmeldung/Benachrichtigung des StbM an die SW-C via RTE).</li>\n<li>Auf BSW-Ebene (API 0) interagiert der StbM über standardisierte C-Schnittstellen (<code>Standardized Interface</code>) direkt über den horizontalen Bus-/Signalpfad mit <code>Operating System</code>, <code>Communication</code>, <code>ECU Abstraction</code> und <code>Microcontroller Abstraction</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Schaubild veranschaulicht normativ die Rolle des StbM als AUTOSAR-Service mit VFB-Schnittstelle: SW-Cs dürfen ausschließlich über die durch die RTE vermittelten AUTOSAR Interfaces (Ports) auf den StbM zugreifen und von ihm benachrichtigt werden.</li>\n<li>Direkte C-Funktionsaufrufe (API 0 / Standardized Interfaces) zwischen SW-Cs und StbM sind architektonisch unzulässig; API 0 ist BSW-internen Modulbeziehungen (z. B. Kopplung an Bus-Treiber/Communication Stack oder OS-Timer) vorbehalten.</li>\n</ul>"}, {"id": "FIG-7acc76926b2251ca", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Blockschaltbild der AUTOSAR-Classic-ECU-Architektur (AUTOSAR Layered Architecture). Das Diagramm verortet das Basissoftware-Modul <code>StbM</code> (Synchronized Time-Base Manager) als AUTOSAR-Service innerhalb der Basissoftware (BSW) und stellt dessen Einbindung über die AUTOSAR Runtime Environment (RTE) zu den Application Software Components (SW-Cs) sowie zu benachbarten BSW-Schichten dar. Eine Legende klassifiziert Schnittstellentypen und API-Kategorien (API 0, API 1, API 2).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Application Layer</strong>: Mehrere <code>Application Software Component</code>-Blöcke, angebunden über gepunktete Ports des Typs <code>AUTOSAR Interface</code>.</li>\n<li><strong>RTE-Schicht</strong>: <code>AUTOSAR Runtime Environment (RTE)</code> als horizontaler Abstraktionsbalken zwischen Applikationsebene und BSW.</li>\n<li><strong>Basissoftware (BSW)</strong>:</li>\n<li><code>StbM</code> (hervorgehoben): BSW-Service mit oberseitigem <code>AUTOSAR Interface</code> (gepunktet, API 2 / VFB & RTE relevant) zur RTE sowie unterseitigem <code>Standardized Interface</code> (gestreift, API 0).</li>\n<li><code>Operating System</code>: Verfügt über ein oberseitiges <code>Standardized Interface</code> (API 1 RTE relevant) und ein vertikales <code>Standardized Interface</code> (API 0).</li>\n<li><code>Communication</code>: Verfügt über ein oberseitiges <code>Standardized Interface</code> (API 1 RTE relevant) und ein unterseitiges <code>Standardized Interface</code> (API 0).</li>\n<li><code>ECU Abstraction</code>: Oberseitig <code>AUTOSAR Interface</code> (API 2) und unterseitig <code>Standardized Interface</code> (API 0).</li>\n<li><code>Microcontroller Abstraction</code> (MCAL): Schnittstellenblock <code>Standardized Interface</code> (API 0).</li>\n<li><code>Complex Device Drivers</code>: Durchgängiger Block mit oberseitigem <code>AUTOSAR Interface</code> (API 2).</li>\n<li><strong>Legende</strong>:</li>\n<li>Schnittstellenarten: <code>AUTOSAR Interface</code> (Punkte-Muster), <code>Standardized Interface</code> (Streifen-Muster).</li>\n<li>Schichtkategorien: <code>AUTOSAR Software Component</code>, <code>ECU Firmware</code>, <code>Standard Software</code>.</li>\n<li>API-Klassifikation: <code>API 2 VFB &amp; RTE relevant</code> (blauer Doppelpfeil), <code>API 1 RTE relevant</code> (oranger Pfeil), <code>API 0</code> (grüner Haken-/Verbindungspfeil).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Ein einzelner gelber Leitfragen-Pfeil fokussiert auf das oberseitige <code>AUTOSAR Interface</code> des StbM mit der Fragestellung: <em>„How does the SW-C access the Synchronized Time-base Mgr?“</em>.</li>\n<li>Auf BSW-Ebene (API 0) interagiert der StbM über standardisierte C-Schnittstellen (<code>Standardized Interface</code>) direkt über den horizontalen Bus-/Signalpfad mit <code>Operating System</code>, <code>Communication</code>, <code>ECU Abstraction</code> und <code>Microcontroller Abstraction</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Schaubild veranschaulicht normativ die Rolle des StbM als AUTOSAR-Service: Die Interaktion von Application Software Components mit dem StbM erfolgt gerichtet über das definierte AUTOSAR Interface vermittelt durch die RTE.</li>\n<li>Ein gesonderter Benachrichtigungspfad für asynchrone Callbacks an die SW-C wird auf dieser Architekturebene im Schaubild nicht mehr separat als eigener Interaktionsweg ausgewiesen.</li>\n<li>BSW-interne Interaktionen laufen unverändert über standardisierte C-APIs (API 0).</li>\n</ul>"}], "trans": [{"from": "FIG-e665c53516e1c945", "to": "FIG-72d4d3b7c5090e86", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-72d4d3b7c5090e86", "to": "FIG-7acc76926b2251ca", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Oberer Annotationsbereich: Der gelbe Hinweispfeil mit der Beschriftung „How the SW-C gets notified from the Synchronized Timebase Manager?“ sowie der orange Hinweispfeil wurden entfernt; stattdessen zeigt ein einzelner gelber Pfeil mit der Beschriftung „How does the SW-C access the Synchronized Time-base Mgr?“ auf das AUTOSAR Interface des StbM.</li>\n</ul>"}]};
